  `correct_rate` double DEFAULT '0' COMMENT '当日正确率',
  `study_seconds` int DEFAULT '0' COMMENT '当日学习时长(秒)',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_date` (`user_id`,`study_date`),
  KEY `idx_user_date` (`user_id`,`study_date`),
  CONSTRAINT `daily_stats_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
