--
-- Table structure for table `user_vocab`
--

DROP TABLE IF EXISTS `user_vocab`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user_vocab` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `vocab_id` bigint NOT NULL,
  `status` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT 'new' COMMENT 'new/learning/review/mature',
  `difficulty` double DEFAULT '5' COMMENT '难度 D (1-10)',
  `stability` double DEFAULT '0' COMMENT '稳定性 S (天)',
  `retrievability` double DEFAULT '1' COMMENT '可检索性 R (0-1)',
  `due_date` datetime DEFAULT NULL COMMENT '下次复习时间',
  `last_review` datetime DEFAULT NULL COMMENT '上次复习时间',
  `review_count` int DEFAULT '0' COMMENT '总复习次数',
  `correct_count` int DEFAULT '0' COMMENT '正确次数',
  `lapse_count` int DEFAULT '0' COMMENT '遗忘次数',
  `first_seen` datetime DEFAULT NULL COMMENT '首次学习时间',
  `last_rating` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '上次评分 again/hard/good/easy',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_vocab` (`user_id`,`vocab_id`),
  KEY `vocab_id` (`vocab_id`),
  KEY `idx_user_due` (`user_id`,`due_date`),
  KEY `idx_user_status` (`user_id`,`status`),
  CONSTRAINT `user_vocab_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `user_vocab_ibfk_2` FOREIGN KEY (`vocab_id`) REFERENCES `vocab` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

