--
-- Table structure for table `vocab`
--

DROP TABLE IF EXISTS `vocab`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vocab` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `word` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '俄语单词（原形/词典形式）',
  `stress` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '带重音标记的单词',
  `chinese` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '中文释义',
  `pos` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '词性 noun.m/noun.f/noun.n/verb/adj/adv/phrase/idiom',
  `level` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'A1/A2/B1/B2',
  `frequency` int DEFAULT '0' COMMENT '语料库中出现次数',
  `episode_count` int DEFAULT '0' COMMENT '出现在多少集中',
  `audio_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'TTS音频URL（可选）',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_word` (`word`),
  KEY `idx_level` (`level`),
  KEY `idx_frequency` (`frequency` DESC)
) ENGINE=InnoDB AUTO_INCREMENT=4915 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
