--
-- Table structure for table `vocab_episodes`
--

DROP TABLE IF EXISTS `vocab_episodes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `vocab_episodes` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `vocab_id` bigint NOT NULL,
  `episode_id` bigint NOT NULL,
  `context_sentence` text COLLATE utf8mb4_unicode_ci COMMENT '该集中的例句',
  `context_translation` text COLLATE utf8mb4_unicode_ci COMMENT '例句中文翻译',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_vocab_episode` (`vocab_id`,`episode_id`),
  KEY `idx_vocab_id` (`vocab_id`),
  KEY `idx_episode_id` (`episode_id`),
  CONSTRAINT `vocab_episodes_ibfk_1` FOREIGN KEY (`vocab_id`) REFERENCES `vocab` (`id`) ON DELETE CASCADE,
  CONSTRAINT `vocab_episodes_ibfk_2` FOREIGN KEY (`episode_id`) REFERENCES `episodes` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=51868 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

